schema_ddl:
CREATE TYPE tipo_movimento AS ENUM ('entrata', 'uscita', 'rettifica');

CREATE TYPE stato_documento AS ENUM ('bozza', 'registrato', 'verificato', 'chiuso', 'annullato');

CREATE TABLE movimenti_contabili (
    id INT PRIMARY KEY,
    numero_protocollo BIGINT NOT NULL UNIQUE,
    data_registrazione DATE NOT NULL,
    descrizione TEXT NOT NULL,
    tipo tipo_movimento NOT NULL,
    stato stato_documento NOT NULL DEFAULT 'bozza',
    importo NUMERIC(12,2) NOT NULL CHECK (importo > 0),
    conto TEXT NOT NULL,
    causale TEXT
);
